pplication	application;	// Allocate application object		application.Run();						// Well lets run it then!	}	catch(CException_AC& theException)	{		DoCatchMessageAndStop_AC(theException);		::BailOutAlert(theException);	}	catch(std::exception& ex)			{		DoCatchISOMessageAndStop_AC(ex);		::BailOutAlert(ex);	}	catch(...)	{		DoCatchForeignMessageAndStop_AC();		::BailOutAlert();	}}//----------------------------------------------------------------------------------------// End of MTest.cp